window.JeiV6Colors=["#0F2F57", "#0f2f57", "#0f2f5710", "#0f2f5733", "#2C64C8", "#2c64c8", "#383838", "#5e6b80", "#E5303A", "#a9aeb6", "#b81f2e", "#b81f2e12", "#b81f2e20", "#cbd2dc", "#cfd6df", "#d62532", "#e0e4e9", "#e3e6eb", "#e3e8f0", "#e4eefb", "#e5303a", "#e5303a24", "#e5e7eb", "#e8ebef", "#edb6bc", "#eee1bb", "#efc3c4", "#f0c7ca", "#f0d1bf", "#f3f4f6", "#f4b8b8", "#f8f9fb", "#fddcd6", "#fde4e0", "#fff", "#fff3f2", "#fff4ee", "#fff4f1", "#fff8e5", "#fff8f3", "#fff9eb"];
(function(){
'use strict';
const C=window.JeiOKLCH,root=document.documentElement,dock=document.querySelector('#report-dock'),key='jei-report-v6-oklch';
const host=dock.querySelector('#color-editor'),presets=[['레드','#e5303a'],['코랄','#cf725b'],['앰버','#b78328'],['그린','#328472'],['블루','#5379ae'],['퍼플','#8b64a7']];
host.innerHTML=`<h3>전체 컬러</h3><p>기준 색을 바꾸면 밝고 진한 단계가 함께 바뀌어요.</p><div class="color-presets">${presets.map(([name,color])=>`<button type="button" data-palette="${color}" style="--swatch:${color}" aria-label="${name} 컬러" aria-pressed="false" title="${name}"></button>`).join('')}</div><div class="color-entry"><input id="palette-picker" type="color" value="#e5303a" aria-label="기준 색 선택"><input id="palette-hex" type="text" value="#E5303A" maxlength="7" spellcheck="false" aria-label="HEX 색상" placeholder="#E5303A"></div><details><summary>직접 조정 · OKLCH</summary>${[['l','밝기 L',15,90,1],['c','선명도 C',0,0.32,0.005],['h','색상 H',0,360,1]].map(([id,name,min,max,step])=>`<label class="color-slider">${name}<output id="value-${id}"></output><input aria-label="${name}" id="color-${id}" type="range" min="${min}" max="${max}" step="${step}"></label>`).join('')}</details><div class="color-scale" aria-label="배경부터 강조까지의 색상 단계"></div><p>배경 → 카드 → 테두리 → 버튼 → 텍스트</p><p id="palette-status" role="status" aria-live="polite"></p><div class="color-actions"><button type="button" id="palette-reset">컬러 초기화</button></div>`;
const originalColors=window.JeiReportColors,originalRail=window.JeiReportRailIcons,baseInline=new Map([...root.style].map(k=>[k,root.style.getPropertyValue(k)])),originalSource=new Map();let chosen=null,values=C.lab('#e5303a'),palette=null,serial=0,frame=0;
const roleMap={page:'page',pageEnd:'page',surface:'surface',surfaceAlt:'surfaceAlt',soft:'soft',softStrong:'activeHover',title:'text',text:'text',muted:'muted',line:'border',lineStrong:'strongBorder',accent:'accent',primary:'primary',primaryHover:'hover',onPrimary:'onPrimary',brand:'text',active:'active',onActive:'text',completed:'surface',locked:'surfaceAlt',disabled:'disabled',night:'night',nightSurface:'night',nightLine:'muted',nightText:'soft'};
function paintColor(hex){if(!palette)return hex;const clean=hex.toLowerCase();if(clean==='#ffffff'||clean==='#fff')return '#ffffff';const suffix=clean.length===9?clean.slice(7):'';let h=clean.slice(0,7);if(h.length===4)h='#'+[...h.slice(1)].map(x=>x+x).join('');const lookup={'#e5303a':palette.accent,'#d62532':palette.primary,'#b81f2e':palette.hover,'#fde4e0':palette.active,'#fddcd6':palette.activeHover,'#0f2f57':palette.text,'#383838':palette.text,'#5e6b80':palette.muted,'#f3f4f6':palette.surfaceAlt,'#202124':'#202124','#52749a':'#52749a','#2c64c8':'#52749a'};
if(lookup[h])return lookup[h]+suffix;const tone=C.lab(h);return C.hex(tone.l,Math.min(tone.c,palette.v.c*(tone.l>.85?.22:.55)),palette.v.h)+suffix;}
function transform(src){const original=originalSource.get(src)||src;if(!original.startsWith('data:image/svg+xml;base64,'))return src;if(!palette)return original;const svg=atob(original.split(',')[1]).replace(/#[\da-f]{6}(?:[\da-f]{2})?\b/gi,paintColor);const next='data:image/svg+xml;base64,'+btoa(svg);originalSource.set(next,original);return next;}
function images(){for(const img of document.querySelectorAll('#report-ui-plane img,dialog img')){const src=img.getAttribute('src')||'',next=transform(src);if(src!==next)img.setAttribute('src',next);}}
function apply(){serial++;palette=chosen?C.palette(values):null;
 if(!palette){root.removeAttribute('data-custom-palette');for(const k of [...root.style])if(k.startsWith('--v6-c-'))root.style.removeProperty(k);for(const [k,v]of baseInline)root.style.setProperty(k,v);window.JeiReportRailIcons=originalRail;}
 else{root.setAttribute('data-custom-palette','true');for(const [k,v]of baseInline)if(/^#[\da-f]{3,8}$/i.test(v))root.style.setProperty(k,paintColor(v));for(const [role,name]of Object.entries(roleMap))root.style.setProperty('--theme-'+role.replace(/[A-Z]/g,c=>'-'+c.toLowerCase()),palette[name]);root.style.setProperty('--theme-overlay',palette.night+'55');root.style.setProperty('--jei-accent',palette.accent);root.style.setProperty('--jei-on-accent',palette.text);root.style.setProperty('--report-header-color','#ffffff');
 for(const color of window.JeiV6Colors)root.style.setProperty('--v6-c-'+color.slice(1),paintColor(color));window.JeiReportRailIcons=Object.freeze(Object.fromEntries(Object.entries(originalRail).map(([k,v])=>[k,transform(v)])));}
 images();sync();try{localStorage.setItem(key,JSON.stringify(chosen?values:null));}catch{}}
function sync(){const p=palette||C.palette(values),hex=C.hex(values.l,values.c,values.h);host.querySelector('#palette-picker').value=hex;host.querySelector('#palette-hex').value=hex.toUpperCase();for(const id of ['l','c','h']){const n=id==='l'?values.l*100:values[id];host.querySelector('#color-'+id).value=n;host.querySelector('#value-'+id).textContent=id==='l'?Math.round(n)+'%':id==='h'?Math.round(n)+'°':n.toFixed(3);}for(const b of host.querySelectorAll('[data-palette]'))b.setAttribute('aria-pressed',String(!!chosen&&b.dataset.palette.toLowerCase()===hex.toLowerCase()));host.querySelector('.color-scale').innerHTML=['page','active','border','primary','text'].map(k=>`<i style="background:${p[k]}"></i>`).join('');host.querySelector('#palette-status').textContent=palette?'선택 컬러 적용 중 · 버튼 글자 대비 '+C.contrast(p.primary,'#ffffff').toFixed(1)+':1':'기본 보고용 컬러';}
window.JeiReportColors=Object.freeze({...originalColors,get current(){return originalColors.current;},asset:(...args)=>transform(originalColors.asset(...args)),syncImages:(...args)=>{originalColors.syncImages(...args);images();},select:async(...args)=>{const run=serial;const result=await originalColors.select(...args);if(palette&&run===serial)apply();return result;}});
let queued=false;new MutationObserver(records=>{if(!records.some(r=>!dock.contains(r.target)))return;if(!queued){queued=true;requestAnimationFrame(()=>{queued=false;images();});}}).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['src']});
function choose(hex){if(!/^#[\da-f]{6}$/i.test(hex))return false;values=C.lab(hex);chosen=true;apply();return true;}
host.addEventListener('click',e=>{const b=e.target.closest('[data-palette]');if(b)choose(b.dataset.palette);if(e.target.closest('#palette-reset')){chosen=null;values=C.lab('#e5303a');apply();originalColors.select(originalColors.current).then(()=>{if(!chosen){images();sync();}});}});
host.querySelector('#palette-picker').addEventListener('input',e=>choose(e.target.value));host.querySelector('#palette-hex').addEventListener('change',e=>{if(!choose(e.target.value)){e.target.setCustomValidity('예: #E5303A 형식으로 입력해주세요.');e.target.reportValidity();}else e.target.setCustomValidity('');});host.querySelector('#palette-hex').addEventListener('input',e=>e.target.setCustomValidity(''));
for(const id of ['l','c','h'])host.querySelector('#color-'+id).addEventListener('input',e=>{values[id]=Number(e.target.value)/(id==='l'?100:1);chosen=true;cancelAnimationFrame(frame);frame=requestAnimationFrame(apply);});
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&['l','c','h'].every(k=>Number.isFinite(saved[k]))){values=saved;chosen=true;}}catch{}apply();
})();
